SELECT id, create_user_name AS createUserName, create_time AS createTime, name, type_id AS typeId , charge_id AS chargeId, contacts, contact_tel_number AS contactTelNumber, disabled, address, warehouse_manage_type AS warehouseManageType, geography_location AS geographyLocation, org_id AS orgId, kingdee_warehouse_code AS kingdeeWarehouseCode, is_virtual AS isVirtual, approve_status AS approveStatus, is_enable_location as isEnableLocation FROM warehouse WHERE ${params.sqlMap.default} and is_deleted=false
AND create_user_id IN
#{createUserId}
AND disabled = #{params.disabled}
AND is_virtual = #{params.isVirtual}
AND warehouse_manage_type = #{params.warehouseManageType}
AND geography_location = #{params.geographyLocation}
AND is_enable_location = #{params.isEnableLocation}
AND address ILIKE concat('%', #{params.address}::text ,'%')
AND kingdee_warehouse_code ILIKE concat('%', #{params.kingdeeWarehouseCode}::text ,'%')
AND name ILIKE concat('%', #{params.name}::text ,'%')
AND contacts ILIKE concat('%', #{params.contacts}::text ,'%')
AND org_id IN
#{item}
AND type_id IN
#{typeId}
AND approve_status IN
#{approveStatus}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
create_time desc

