SELECT id AS warehouseId, name, type_id AS typeId , disabled, org_id AS orgId, kingdee_warehouse_code AS code FROM warehouse WHERE is_deleted=false and approve_status = 'approve'
AND name ILIKE concat('%', #{params.name}::text ,'%')
AND kingdee_warehouse_code ILIKE concat('%', #{params.code}::text ,'%')
AND type_id IN
#{typeId}
AND org_id IN
#{item}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
"name" ASC

